  push!(__eqs, apparent.WorldSpeed_y ~ Current_y)
  push!(__eqs, ShipSpeed ~ apparent.SpeedLocal_x)
  push!(__eqs, Wake_Fraction ~ WakeFraction)
  push!(__eqs, w ~ ModelingToolkit.D_nounits(flange.phi))
  push!(__eqs, w_eff ~ sqrt(w ^ 2 + w_floor ^ 2))
  push!(__eqs, n ~ w_eff / (2 * π))
  push!(__eqs, rpm ~ w * 60 / (2 * π))
  push!(__eqs, AdvanceSpeed ~ ShipSpeed * (1 - WakeFraction))
  push!(__eqs, J ~ clamp(AdvanceSpeed / (n * Diameter), J_min, J_max))
  push!(__eqs, Kt ~ wageningen_kt(J, P_D, Ae_Ao, Z))
  push!(__eqs, Kq ~ wageningen_kq(J, P_D, Ae_Ao, Z))
  push!(__eqs, Thrust_Kt ~ Kt * SeaDensity * n ^ 2 * Diameter ^ 4)
  push!(__eqs, Torque_Kq ~ Kq * SeaDensity * n ^ 2 * Diameter ^ 5)
  push!(__eqs, flange.tau ~ Torque_Kq * w / w_eff)
  push!(__eqs, Thrust ~ Thrust_Kt * (1 - ThrustDeduction))
  push!(__eqs, force.force_x ~ Thrust)
  push!(__eqs, force.force_y ~ 0)
  push!(__eqs, force.force_z ~ 0)
  push!(__eqs, torque.torque_x ~ -flange.tau)
  push!(__eqs, torque.torque_y ~ 0)
  push!(__eqs, torque.torque_z ~ 0)
  push!(__eqs, Nu_zero ~ J / (2 * π) * Kt / (Kq + 0.000001))
  push!(__eqs, Nu_hull ~ (1 - ThrustDeduction) / (1 - WakeFraction))
  push!(__eqs, Nu_propulsive ~ Nu_zero * RotativeRelative * Nu_hull)
  push!(__eqs, ShaftPower ~ w * flange.tau)
  push!(__eqs, ThrustPower ~ Thrust * ShipSpeed)
  push!(__eqs, C_th ~ sqrt(8 * w_eff ^ 2 * Diameter ^ 2 * abs(Kt) / (π * (AdvanceSpeed ^ 2 + 0.000001))))
  push!(__eqs, V_inf ~ sqrt(AdvanceSpeed ^ 2 + 0.000001) * sqrt(1 + C_th))
  push!(__eqs, r_inf ~ (Diameter / 2) * sqrt(0.5 * (1 + AdvanceSpeed / V_inf)))
  push!(__eqs, r_x ~ (Diameter / 2) * (0.14 * (r_inf / (Diameter / 2)) ^ 3 + (r_inf / (Diameter / 2)) * (Rudder_distance / (Diameter / 2)) ^ 1.5) / (0.14 * (r_inf / (Diameter / 2)) ^ 3 + (Rudder_distance / (Diameter / 2)) ^ 1.5))
  push!(__eqs, V_x ~ V_inf * (r_inf / r_x) ^ 2)
  push!(__eqs, Delta_r ~ 0.15 * Rudder_distance * ((V_inf * r_inf ^ 2 - AdvanceSpeed * r_x ^ 2) / (V_inf * r_inf ^ 2 + AdvanceSpeed * r_x ^ 2)))
  push!(__eqs, Propeller_flow_diameter ~ 2 * (r_x + Delta_r))
  push!(__eqs, Propeller_speed ~ (V_x - AdvanceSpeed) * (r_x ^ 2 / (r_x + Delta_r) ^ 2) + AdvanceSpeed)
  push!(__eqs, connect(frame_a, apparent.frame_a, force.frame_b, torque.frame_b))

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export Propeller1Q
